const fmt=n=>new Intl.NumberFormat('ru-RU').format(Math.round(n||0))+' ₽';
const initials=n=>(n||'—').split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase();
const monthNames={"2026-01":'Январь 2026',"2026-02":'Февраль 2026',"2026-03":'Март 2026'};
const statuses=[['new','Новая заявка','#7e9c91'],['work','В работе','#4c7fbd'],['proposal','КП отправлено','#d69232'],['paid','Оплата','#40a36e'],['closed','Закрыта / отказ','#b36a6a']];
const seed={
 users:[{id:'u1',name:'Вася К.',login:'admin',pass:'Admin2026!',role:'admin'},{id:'u2',name:'Алина',login:'alina',pass:'Manager2026!',role:'manager'},{id:'u3',name:'Паша',login:'pasha',pass:'Manager2026!',role:'manager'}],
 leads:[
 {id:1,name:'Светлана',request:'Навести порядок в финансах и накопить на пенсию',status:'new',owner:'u2',sum:0,tariff:'Сам',comment:'Новый лид'},
 {id:2,name:'Яна',request:'Планировать крупные покупки',status:'paid',owner:'u2',sum:54990,tariff:'Куратор'},
 {id:3,name:'Майя',request:'Создать финансовую подушку',status:'work',owner:'u2',sum:54990,tariff:'Куратор',comment:'Созвон сегодня'},
 {id:4,name:'Лариса',request:'Система управления личными финансами',status:'proposal',owner:'u2',sum:34990,tariff:'Сам'},
 {id:5,name:'Екатерина',request:'Планирование на 10–15 лет',status:'paid',owner:'u3',sum:59900,tariff:'Куратор'},
 {id:6,name:'Таня',request:'Не могу планировать бюджет',status:'proposal',owner:'u3',sum:54990,tariff:'Куратор'},
 {id:7,name:'Мария',request:'Планирование и накопление',status:'work',owner:'u3',sum:0,tariff:'VIP'},
 {id:8,name:'Данил',request:'Хочу попасть на последний поток',status:'new',owner:'u3',sum:0,tariff:'Сам'},
 {id:9,name:'Валя',request:'Инвестиционный план',status:'closed',owner:'u1',sum:79990,tariff:'VIP'}],
 payments:[
 {id:1,name:'Дарья',tariff:'Куратор',revenue:44990,net:43415,debt:0,method:'Сразу',date:'05.01.2026',owner:'Алина',month:'2026-01'},
 {id:2,name:'Роман',tariff:'Сам',revenue:34990,net:28692,debt:0,method:'Рассрочка',date:'12.01.2026',owner:'Паша',month:'2026-01'},
 {id:3,name:'Ольга',tariff:'Куратор',revenue:44990,net:43415,debt:0,method:'Сразу',date:'21.01.2026',owner:'Алина',month:'2026-01'},
 {id:4,name:'Глеб',tariff:'Куратор',revenue:54990,net:45992,debt:9000,method:'Рассрочка',date:'02.02.2026',owner:'Паша',month:'2026-02'},
 {id:5,name:'Валентин',tariff:'VIP',revenue:79990,net:65592,debt:0,method:'Рассрочка',date:'06.02.2026',owner:'Алина',month:'2026-02'},
 {id:6,name:'Екатерина',tariff:'VIP',revenue:79990,net:69111,debt:10879,method:'Рассрочка',date:'10.02.2026',owner:'Вася К.',month:'2026-02'},
 {id:7,name:'Яна',tariff:'VIP',revenue:71990,net:69470,debt:0,method:'Сразу',date:'14.02.2026',owner:'Алина',month:'2026-02'},
 {id:8,name:'Наталья',tariff:'Сам',revenue:34990,net:33765,debt:0,method:'Сразу',date:'18.02.2026',owner:'Паша',month:'2026-02'}],
 plans:{'2026-01':{min:900000,target:1400000,max:1900000},'2026-02':{min:1000000,target:1500000,max:2100000},'2026-03':{min:1100000,target:1650000,max:2300000}},
 terms:{'2026-01':{u1:{salary:110000,rate:5,actual:720000},u2:{salary:70000,rate:4,actual:1085000},u3:{salary:70000,rate:4,actual:925000}},'2026-02':{u1:{salary:110000,rate:5,actual:820000},u2:{salary:75000,rate:4.5,actual:1319086},u3:{salary:75000,rate:4,actual:1451142}},'2026-03':{u1:{salary:115000,rate:5,actual:460000},u2:{salary:80000,rate:5,actual:840000},u3:{salary:80000,rate:4.5,actual:710000}}}
};
let state=seed,current=null,page='kanban',month='2026-02',teamTab='plans',leadFilters={owner:'all',tariff:'all'},payFilters={owner:'all',tariff:'all',method:'all'},sort={key:'date',dir:-1};
const save=async()=>{try{let r=await fetch('/api/state',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(state)});if(!r.ok)throw new Error(await r.text())}catch(e){console.error(e);toast('Не удалось сохранить данные')}};
const ownerName=id=>(state.users.find(u=>u.id===id)||{}).name||'—';
const terms=(u,m=month)=>(state.terms[m]||{})[u.id]||{salary:0,rate:0,actual:0};
const plan=(m=month)=>state.plans[m]||{min:0,target:1,max:1};
const bonus=(u,m=month)=>{let t=terms(u,m),p=plan(m),k=t.actual>=p.max?1.6:t.actual>=p.target?1.35:t.actual>=p.min?1.15:0;return Math.round(t.actual*t.rate/100*k)};
const options=(items,value)=>items.map(x=>`<option value="${x}" ${x===value?'selected':''}>${x==='all'?'Все':x}</option>`).join('');
function toast(t){toastEl.textContent=t;toastEl.classList.add('show');setTimeout(()=>toastEl.classList.remove('show'),2000)}
const toastEl=document.getElementById('toast');
function loginAs(type){let u=type==='admin'?state.users[0]:state.users[1];username.value=u.login;password.value=u.pass;hint.textContent=u.login+' · '+u.pass;document.querySelectorAll('[data-demo]').forEach(b=>b.classList.toggle('active',b.dataset.demo===type))}
document.querySelectorAll('[data-demo]').forEach(b=>b.onclick=()=>loginAs(b.dataset.demo));
showPass.onclick=()=>{password.type=password.type==='password'?'text':'password';showPass.textContent=password.type==='password'?'Показать':'Скрыть'};
loginForm.onsubmit=e=>{e.preventDefault();let u=state.users.find(x=>x.login===username.value&&x.pass===password.value);if(!u)return toast('Неверный логин или пароль');current=u;login.classList.add('hidden');app.classList.remove('hidden');document.querySelectorAll('.admin-only').forEach(x=>x.classList.toggle('hidden',u.role!=='admin'));sideName.textContent=u.name;sideRole.textContent=u.role==='admin'?'Руководитель':'Менеджер';topAvatar.textContent=initials(u.name);page=u.role==='admin'?'kanban':'workspace';render()};
logout.onclick=()=>{app.classList.add('hidden');login.classList.remove('hidden')};menuBtn.onclick=()=>document.querySelector('.sidebar').classList.toggle('open');
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;render();document.querySelector('.sidebar').classList.remove('open')});
function setNav(){document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));let map={workspace:['Рабочий стол','Ваш результат и фокус на сегодня'],kanban:['Заявки','Управление воронкой продаж'],payments:['Оплаты','Выручка, прибыль и дебиторка'],plans:['Дашборд','План-факт и динамика поступлений'],team:['Сотрудники','Планы и история условий']};pageTitle.textContent=map[page][0];pageSub.textContent=map[page][1];leadBadge.textContent=state.leads.filter(x=>!['paid','closed'].includes(x.status)&&(current.role==='admin'||x.owner===current.id)).length}
function render(){setNav();({workspace:renderWorkspace,kanban:renderKanban,payments:renderPayments,plans:renderDashboard,team:renderTeam}[page])()}
const filterBar=(kind)=>kind==='leads'?`<div class="filter-bar"><label>Менеджер<select onchange="leadFilters.owner=this.value;renderKanban()">${options(['all',...state.users.map(u=>u.id)],leadFilters.owner).replace(/>u(\d)</g,(m,n)=>'>'+ownerName('u'+n)+'</')}</select></label><label>Тариф<select onchange="leadFilters.tariff=this.value;renderKanban()">${options(['all','Сам','Куратор','VIP'],leadFilters.tariff)}</select></label><button class="clear-filter" onclick="leadFilters={owner:'all',tariff:'all'};renderKanban()">Сбросить</button></div>`:`<div class="filter-bar"><label>Менеджер<select onchange="payFilters.owner=this.value;renderPayments()">${options(['all',...state.users.map(u=>u.name)],payFilters.owner)}</select></label><label>Тариф<select onchange="payFilters.tariff=this.value;renderPayments()">${options(['all','Сам','Куратор','VIP'],payFilters.tariff)}</select></label><label>Способ оплаты<select onchange="payFilters.method=this.value;renderPayments()">${options(['all','Сразу','Рассрочка'],payFilters.method)}</select></label><button class="clear-filter" onclick="payFilters={owner:'all',tariff:'all',method:'all'};renderPayments()">Сбросить</button></div>`;
function filteredLeads(){return state.leads.filter(l=>(current.role==='admin'||l.owner===current.id)&&(leadFilters.owner==='all'||l.owner===leadFilters.owner)&&(leadFilters.tariff==='all'||l.tariff===leadFilters.tariff))}
function renderKanban(){let leads=filteredLeads();content.innerHTML=`<div class="fixed-page"><div class="page-tools"><div>${current.role==='admin'?filterBar('leads'):''}</div><button class="primary" onclick="leadModal()">+ Новая заявка</button></div><div class="kanban">${statuses.map(s=>`<div class="kanban-col" data-status="${s[0]}"><div class="col-head"><i class="dot" style="background:${s[2]}"></i>${s[1]}<b>${leads.filter(x=>x.status===s[0]).length}</b></div><div class="column-scroll">${leads.filter(x=>x.status===s[0]).map(leadCard).join('')||'<div class="empty">Нет заявок</div>'}</div></div>`).join('')}</div></div>`;bindDrag()}
function leadCard(l){return `<article class="lead-card" draggable="true" data-id="${l.id}" onclick="leadModal(${l.id})"><div class="lead-top"><div><h3>${l.name}</h3><span class="company">${ownerName(l.owner)}</span></div><span class="tag">${l.tariff||'Без тарифа'}</span></div><p>${l.request}</p><div class="lead-bottom"><strong>${l.sum?fmt(l.sum):l.comment||'Новая заявка'}</strong><span class="mini-avatar">${initials(ownerName(l.owner))}</span></div></article>`}
function bindDrag(){let d;document.querySelectorAll('.lead-card').forEach(c=>{c.ondragstart=e=>{d=c;e.stopPropagation()}});document.querySelectorAll('.kanban-col').forEach(col=>{col.ondragover=e=>e.preventDefault();col.ondrop=()=>{state.leads.find(x=>x.id==d.dataset.id).status=col.dataset.status;save();renderKanban()}})}
function filteredPayments(){return state.payments.filter(p=>(current.role==='admin'||p.owner===current.name)&&(payFilters.owner==='all'||p.owner===payFilters.owner)&&(payFilters.tariff==='all'||p.tariff===payFilters.tariff)&&(payFilters.method==='all'||p.method===payFilters.method)).sort((a,b)=>{let x=a[sort.key],y=b[sort.key];if(sort.key==='date'){x=x.split('.').reverse().join('');y=y.split('.').reverse().join('')}return(x>y?1:x<y?-1:0)*sort.dir})}
function sortBy(k){sort=k===sort.key?{key:k,dir:-sort.dir}:{key:k,dir:-1};renderPayments()}
const th=(label,key)=>`<th onclick="sortBy('${key}')">${label}<span class="sort-mark">${sort.key===key?(sort.dir>0?'↑':'↓'):'↕'}</span></th>`;
function renderPayments(){let rows=filteredPayments(),revenue=rows.reduce((a,b)=>a+b.revenue,0),net=rows.reduce((a,b)=>a+b.net,0),debt=rows.reduce((a,b)=>a+b.debt,0);content.innerHTML=`<div class="fixed-page payments-page"><div class="stats-grid compact"><div class="stat-card"><span>Выручка</span><strong>${fmt(revenue)}</strong></div><div class="stat-card"><span>Чистая прибыль</span><strong>${fmt(net)}</strong></div><div class="stat-card"><span>Дебиторка</span><strong>${fmt(debt)}</strong></div><div class="stat-card"><span>Средний чек</span><strong>${fmt(revenue/(rows.length||1))}</strong></div></div><div class="page-tools"><div>${current.role==='admin'?filterBar('payments'):''}</div><button class="primary" onclick="paymentModal()">+ Внести оплату</button></div><div class="table-wrap table-scroll"><table class="data-table"><thead><tr>${th('Клиент','name')}${th('Тариф','tariff')}${th('Дата','date')}${th('Менеджер','owner')}${th('Способ','method')}${th('Выручка','revenue')}${th('Чистыми','net')}<th>Статус</th></tr></thead><tbody>${rows.map(p=>`<tr><td><strong>${p.name}</strong></td><td>${p.tariff}</td><td>${p.date}</td><td>${p.owner}</td><td>${p.method}</td><td><strong>${fmt(p.revenue)}</strong></td><td>${fmt(p.net)}</td><td><span class="status-pill ${p.debt?'debt':''}">${p.debt?'Долг '+fmt(p.debt):'Оплачено'}</span></td></tr>`).join('')}</tbody></table></div></div>`}
function renderDashboard(){let users=state.users.filter(u=>u.role==='manager'),total=users.reduce((a,u)=>a+terms(u).actual,0),p=plan(),nets=state.payments.filter(x=>x.month===month).reduce((a,x)=>a+x.net,0),weeks=[18,31,27,44,52,38,61];content.innerHTML=`<div class="fixed-page"><div class="page-tools"><div class="month-picker">Период <select onchange="month=this.value;render()">${Object.keys(monthNames).map(m=>`<option value="${m}" ${m===month?'selected':''}>${monthNames[m]}</option>`).join('')}</select></div></div><div class="stats-grid compact"><div class="stat-card"><span>Факт команды</span><strong>${fmt(total)}</strong><small>${Math.round(total/p.target/2*100)}% командного плана</small></div><div class="stat-card"><span>Чистая прибыль</span><strong>${fmt(nets||total*.82)}</strong><small>тестовые данные периода</small></div><div class="stat-card"><span>Целевой план</span><strong>${fmt(p.target*users.length)}</strong><small>${fmt(Math.max(0,p.target*users.length-total))} осталось</small></div><div class="stat-card"><span>Премии</span><strong>${fmt(users.reduce((a,u)=>a+bonus(u),0))}</strong><small>расчёт на сегодня</small></div></div><div class="dashboard-grid fill"><div class="panel"><div class="panel-head"><h3>План-факт по менеджерам</h3><span class="status-pill">${monthNames[month]}</span></div>${users.map(u=>{let t=terms(u),pc=Math.round(t.actual/p.target*100);return `<div class="manager-progress"><div><b>${u.name}</b><span>${fmt(t.actual)} из ${fmt(p.target)}</span></div><div class="small-progress"><i style="width:${Math.min(100,pc)}%"></i></div><strong>${pc}%</strong></div>`}).join('')}</div><div class="panel"><div class="panel-head"><h3>Динамика поступлений</h3><span class="chart-total">${fmt(nets||total*.82)}</span></div><div class="chart">${weeks.map((h,i)=>`<div class="chart-col ${i===6?'active':''}"><b>${h}к</b><i style="height:${h/65*100}%"></i><span>${i+1} нед.</span></div>`).join('')}</div></div></div></div>`}
function renderWorkspace(){let t=terms(current),p=plan(),b=bonus(current),next=t.actual<p.min?p.min:t.actual<p.target?p.target:p.max,pc=Math.round(t.actual/p.target*100),leads=state.leads.filter(x=>x.owner===current.id&&['new','work','proposal'].includes(x.status));content.innerHTML=`<div class="fixed-page workspace-page"><div class="workspace-top"><div class="progress-card"><div class="bonus-now"><span>Премия сейчас</span><strong>${fmt(b)}</strong><small>ставка ${t.rate}% · коэффициент зависит от плана</small></div><div class="progress-main"><div><span>Факт месяца</span><b>${fmt(t.actual)}</b></div><div><span>Целевой план</span><b>${fmt(p.target)}</b></div></div><div class="progress-track"><i style="width:${Math.min(100,pc)}%"></i></div><div class="progress-labels"><span>Минимум ${fmt(p.min)}</span><span>${pc}%</span><span>Максимум ${fmt(p.max)}</span></div></div><div class="next-goal"><span>До следующей ступени</span><strong>${fmt(Math.max(0,next-t.actual))}</strong><p>Это примерно ${Math.max(0,Math.ceil((next-t.actual)/54990))} сделки со средним чеком</p><div class="small-progress"><i style="width:${Math.min(100,t.actual/next*100)}%"></i></div></div></div><div class="panel work-list"><div class="panel-head"><div><h3>В работе</h3><span>${leads.length} активных клиентов</span></div><button class="ghost" onclick="page='kanban';render()">Открыть Kanban →</button></div><div class="work-cards">${leads.map(l=>`<button onclick="page='kanban';leadFilters.owner='${current.id}';render();setTimeout(()=>leadModal(${l.id}),0)"><span class="mini-avatar">${initials(l.name)}</span><span><b>${l.name}</b><small>${l.request}</small></span><em>${statuses.find(s=>s[0]===l.status)[1]}</em><i>→</i></button>`).join('')}</div></div></div>`}
function renderTeam(){content.innerHTML=`<div class="fixed-page"><div class="page-tools"><div class="segmented"><button class="${teamTab==='plans'?'active':''}" onclick="teamTab='plans';renderTeam()">Планы по месяцам</button><button class="${teamTab==='terms'?'active':''}" onclick="teamTab='terms';renderTeam()">Условия сотрудников</button></div><div class="month-picker"><select onchange="month=this.value;renderTeam()">${Object.keys(monthNames).map(m=>`<option value="${m}" ${m===month?'selected':''}>${monthNames[m]}</option>`).join('')}</select></div></div>${teamTab==='plans'?plansEditor():termsEditor()}</div>`}
function plansEditor(){let p=plan();return `<div class="settings-layout"><div class="panel settings-card"><span class="eyebrow">План команды</span><h2>${monthNames[month]}</h2><form onsubmit="savePlan(event)" class="stack-form"><label>План-минимум<input name="min" type="number" value="${p.min}"></label><label>Целевой план<input name="target" type="number" value="${p.target}"></label><label>План-максимум<input name="max" type="number" value="${p.max}"></label><button class="primary">Сохранить план</button></form></div><div class="panel history"><h3>История планов</h3>${Object.entries(state.plans).map(([m,x])=>`<button onclick="month='${m}';renderTeam()"><span><b>${monthNames[m]}</b><small>минимум ${fmt(x.min)}</small></span><strong>${fmt(x.target)}</strong><em>→</em></button>`).join('')}</div></div>`}
function termsEditor(){return `<div class="panel employee-terms"><div class="panel-head"><div><h3>Условия сотрудников</h3><span>Изменения сохраняются только для выбранного месяца</span></div></div>${state.users.map(u=>{let t=terms(u);return `<form onsubmit="saveTerms(event,'${u.id}')" class="terms-row"><div class="member-head"><div class="avatar">${initials(u.name)}</div><div><b>${u.name}</b><span>${u.role==='admin'?'Руководитель':'Менеджер'}</span></div></div><label>Оклад<input name="salary" type="number" value="${t.salary}"></label><label>Ставка, %<input name="rate" type="number" step="0.5" value="${t.rate}"></label><label>Факт месяца<input name="actual" type="number" value="${t.actual}"></label><div><span>Премия</span><strong>${fmt(bonus(u))}</strong></div><button class="ghost">Сохранить</button></form>`}).join('')}</div>`}
function savePlan(e){e.preventDefault();state.plans[month]=Object.fromEntries([...new FormData(e.target)].map(([k,v])=>[k,+v]));save();renderTeam();toast('План месяца сохранён')}
function saveTerms(e,id){e.preventDefault();state.terms[month]??={};state.terms[month][id]=Object.fromEntries([...new FormData(e.target)].map(([k,v])=>[k,+v]));save();renderTeam();toast('Условия сотрудника сохранены')}
function openModal(html){modalBody.innerHTML=html;modal.classList.remove('hidden')}document.querySelector('.modal-close').onclick=()=>modal.classList.add('hidden');modal.onclick=e=>{if(e.target===modal)modal.classList.add('hidden')};
function leadModal(id){let l=state.leads.find(x=>x.id==id)||{name:'',request:'',status:'new',owner:current.id,sum:0,tariff:'Сам'};openModal(`<h2>${id?'Карточка заявки':'Новая заявка'}</h2><form id="leadForm"><div class="form-grid"><label>Имя<input name="name" value="${l.name}" required></label><label>Менеджер<select name="owner">${state.users.map(u=>`<option value="${u.id}" ${u.id===l.owner?'selected':''}>${u.name}</option>`).join('')}</select></label><label>Статус<select name="status">${statuses.map(s=>`<option value="${s[0]}" ${s[0]===l.status?'selected':''}>${s[1]}</option>`).join('')}</select></label><label>Тариф<select name="tariff">${['Сам','Куратор','VIP'].map(x=>`<option ${x===l.tariff?'selected':''}>${x}</option>`).join('')}</select></label><label>Сумма<input name="sum" type="number" value="${l.sum}"></label><label class="full">Запрос<textarea name="request" rows="4">${l.request}</textarea></label></div><div class="modal-actions"><button type="button" class="ghost" onclick="modal.classList.add('hidden')">Отмена</button><button class="primary">Сохранить</button></div></form>`);leadForm.onsubmit=e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));d.sum=+d.sum;if(id)Object.assign(l,d);else state.leads.unshift({id:Date.now(),...d});save();modal.classList.add('hidden');render();toast('Заявка сохранена')}}
function paymentModal(){openModal(`<h2>Новая оплата</h2><form id="payForm"><div class="form-grid"><label>Клиент<input name="name" required></label><label>Менеджер<select name="owner">${state.users.map(u=>`<option>${u.name}</option>`).join('')}</select></label><label>Тариф<select name="tariff"><option>Сам</option><option>Куратор</option><option>VIP</option></select></label><label>Способ<select name="method"><option>Сразу</option><option>Рассрочка</option></select></label><label>Выручка<input name="revenue" type="number" required></label><label>Чистая прибыль<input name="net" type="number" required></label><label>Дебиторка<input name="debt" type="number" value="0"></label></div><div class="modal-actions"><button class="primary">Добавить</button></div></form>`);payForm.onsubmit=e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));['revenue','net','debt'].forEach(k=>d[k]=+d[k]);state.payments.unshift({id:Date.now(),date:new Date().toLocaleDateString('ru-RU'),month,...d});save();modal.classList.add('hidden');renderPayments();toast('Оплата добавлена')}}
globalSearch.oninput=e=>{let q=e.target.value.toLowerCase();document.querySelectorAll('.lead-card').forEach(c=>c.style.display=c.textContent.toLowerCase().includes(q)?'':'none')};
fetch('/api/state').then(r=>{if(!r.ok)throw new Error('API '+r.status);return r.json()}).then(data=>{state=data;loginAs('admin')}).catch(error=>{console.error(error);toast('База недоступна — показаны тестовые данные')});
